  // Archive (Mull+ feature: past daily dilemmas)
  "archive.eyebrow":         { en: "Dilemma archive", es: "Archivo de dilemas", fr: "Archives des dilemmes", pt: "Arquivo de dilemas", ru: "Архив дилемм", zh: "困境存档", ja: "ジレンマ・アーカイブ", ko: "딜레마 아카이브" },
  "archive.title":           { en: "Past daily dilemmas", es: "Dilemas diarios pasados", fr: "Dilemmes quotidiens passés", pt: "Dilemas diários anteriores", ru: "Прошлые дилеммы дня", zh: "过往每日困境", ja: "過去の毎日のジレンマ", ko: "지난 매일의 딜레마" },
  "archive.subtitle":        { en: "Each day's prompt, kept in case you missed it. Mull+ unlocks the ability to write a response and add it to your trajectory.", es: "Cada pregunta del día, conservada por si te la perdiste. Mull+ desbloquea la posibilidad de escribir una respuesta y añadirla a tu trayectoria.", fr: "Chaque dilemme du jour est conservé au cas où tu l'aurais manqué. Mull+ permet d'y répondre et d'ajouter le résultat à ta trajectoire.", pt: "Cada pergunta do dia, guardada caso você a tenha perdido. Mull+ desbloqueia a possibilidade de escrever uma resposta e adicioná-la à sua trajetória.", ru: "Каждая дилемма сохраняется на случай, если вы её пропустили. Mull+ открывает возможность ответить и добавить результат к вашей траектории.", zh: "每日问题都会保留，方便你补回错过的那一天。Mull+ 解锁了在过往日期作答并加入轨迹的能力。", ja: "毎日の問いをすべて保管しています。Mull+ なら過去の問いに回答して軌跡に追加できます。", ko: "매일의 질문은 놓친 날을 위해 보관됩니다. Mull+를 사용하면 과거 질문에 답변하고 궤적에 추가할 수 있습니다." },
  "archive.todays_dilemma":  { en: "Today's dilemma →", es: "Dilema de hoy →", fr: "Dilemme du jour →", pt: "Dilema de hoje →", ru: "Дилемма дня →", zh: "今日困境 →", ja: "今日のジレンマ →", ko: "오늘의 딜레마 →" },
  "archive.signin_required": { en: "Sign in to track which past dilemmas you've answered.", es: "Inicia sesión para llevar registro de qué dilemas pasados has respondido.", fr: "Connecte-toi pour suivre les dilemmes auxquels tu as déjà répondu.", pt: "Entre para acompanhar quais dilemas passados você já respondeu.", ru: "Войдите, чтобы отслеживать, на какие прошлые дилеммы вы уже ответили.", zh: "登录以追踪你已作答过哪些往日困境。", ja: "サインインすると、過去のジレンマのうちどれに回答したかを追跡できます。", ko: "로그인하면 어떤 지난 딜레마에 답했는지 확인할 수 있습니다." },
  "archive.plus_lock_eyebrow": { en: "Mull+ unlocks the archive", es: "Mull+ desbloquea el archivo", fr: "Mull+ déverrouille les archives", pt: "Mull+ desbloqueia o arquivo", ru: "Mull+ открывает архив", zh: "Mull+ 解锁存档", ja: "Mull+ でアーカイブが解放されます", ko: "Mull+로 아카이브 잠금 해제" },
  "archive.plus_lock_body":  { en: "You can read every past prompt for free. Writing a response to a past dilemma — and getting the same Claude analysis you get for today's — is part of Mull+.", es: "Puedes leer todas las preguntas anteriores de forma gratuita. Escribir una respuesta a un dilema pasado y recibir el mismo análisis de Claude que para los actuales forma parte de Mull+.", fr: "Tu peux lire tous les dilemmes passés gratuitement. Y répondre — et obtenir la même analyse Claude que pour les dilemmes actuels — fait partie de Mull+.", pt: "Você pode ler todas as perguntas anteriores gratuitamente. Escrever uma resposta a um dilema passado — e receber a mesma análise do Claude que recebe nos dilemas atuais — faz parte do Mull+.", ru: "Все прошлые дилеммы можно читать бесплатно. Отправлять на них ответы и получать такой же разбор от Claude, как для сегодняшней, — часть Mull+.", zh: "你可以免费阅读所有往日问题。要为过往困境写下回答并获得与今日相同的 Claude 分析，则属于 Mull+ 的功能。", ja: "過去の問いはすべて無料で閲覧できます。過去のジレンマに回答し、今日と同じ Claude による分析を受け取れるのは Mull+ の機能です。", ko: "과거 모든 질문을 무료로 읽을 수 있습니다. 과거 딜레마에 답변하고 오늘과 같은 Claude 분석을 받는 기능은 Mull+에 포함됩니다." },
  "archive.see_plus":        { en: "See Mull+ →", es: "Ver Mull+ →", fr: "Voir Mull+ →", pt: "Ver Mull+ →", ru: "Узнать о Mull+ →", zh: "了解 Mull+ →", ja: "Mull+ を見る →", ko: "Mull+ 보기 →" },
