  "demo.section_intro": { en: "A few optional questions about who's answering help the research. Every field is optional — share only what you're comfortable with, and you can change or clear these any time.", zh: "几个关于答题者的选填问题，有助于研究分析。每一项都是选填——只分享你愿意分享的内容，且随时可以修改或清除。" },
  "demo.gate_title": { en: "Thanks — you're opted in.", zh: "谢谢——你已选择加入。" },
  "demo.gate_intro": { en: "Optionally, a little about you sharpens the research. All optional, all skippable, and editable any time on the /consent page.", zh: "可选地，留下一点关于你的信息能让研究更精准。全部选填、可随时跳过，也可随时在 /consent 页面修改。" },
