  "arena.open_card_title": { en: "A real tournament with brackets", zh: "一场真正的对阵锦标赛" },
  "arena.open_pitch": { en: "Once a quarter, the Arena gets a season-cap event. Top 16 PvP players from the season's leaderboard get seeded; the rest enter via a play-in qualifier. Single-elimination brackets, three judged rounds, finals spectator-viewable with the judge's verdict broken out by round. Annual champion gets a permanent badge and a featured kindred-minds page.", zh: "每季度，竞技场都会迎来一场收官盛事。赛季排行榜上 PvP 前 16 名直接获得种子席位，其余选手通过附加资格赛晋级。单败淘汰赛制，三轮裁决，决赛对公众开放观战，裁判的裁决按回合逐一呈现。年度冠军将获得永久徽章，以及一个专属的「同道」展示页。" },
  "arena.open_doing_1": { en: "Quarterly schedule (Q1/Q2/Q3/Q4) with a 7-day play-in and a 7-day bracket.", zh: "季度赛程（Q1/Q2/Q3/Q4），含为期 7 天的附加赛与 7 天的正赛对阵。" },
  "arena.open_doing_2": { en: "Brackets visible to all signed-in users.", zh: "所有登录用户均可查看对阵表。" },
  "arena.open_doing_3": { en: "Finals are spectator-viewable — read the debates as they happen.", zh: "决赛开放观战——辩论实时可读。" },
  "arena.open_doing_4": { en: "Drops into /atlas as Rigor + Depth + Consistency XP for participants.", zh: "参赛者的表现将以严谨、深度与一致性的经验值计入 /atlas。" },
  "arena.open_when": { en: "Building now. Needs tournament + bracket infra. Earliest ship: Q4 2026. Will launch when the PvP user base hits a threshold to make brackets meaningful.", zh: "正在开发中。需要锦标赛与对阵系统的基础设施。最早上线时间：2026 年第四季度。待 PvP 用户规模达到能让对阵真正有意义的门槛时便会推出。" },
  "arena.open_meantime": { en: "Climb the Arena Elo ladder — that's what'll seed you when the Open opens.", zh: "去竞技场的 Elo 阶梯上攀登吧——公开赛开启时，那将决定你的种子排位。" },
