  "phil.eyebrow":            { en: "From the constellation", es: "Desde la constelación", fr: "Depuis la constellation", pt: "Da constelação", ru: "Из созвездия", zh: "来自星座", ja: "コンステレーションから", ko: "별자리에서" },
  "phil.section_about":      { en: "About", es: "Acerca de", fr: "À propos", pt: "Sobre", ru: "О мыслителе", zh: "简介", ja: "人物紹介", ko: "소개" },
  "phil.section_archetype":  { en: "Their archetype on Mull", es: "Su arquetipo en Mull", fr: "Leur archétype sur Mull", pt: "Seu arquétipo no Mull", ru: "Их архетип на Mull", zh: "他们在 Mull 上的原型", ja: "Mull における彼らのアーキタイプ", ko: "Mull에서의 그들의 원형" },
  "phil.section_dimensions": { en: "Defining dimensions", es: "Dimensiones definitorias", fr: "Dimensions déterminantes", pt: "Dimensões definidoras", ru: "Определяющие измерения", zh: "定义性维度", ja: "中核となる次元", ko: "핵심 차원" },
  "phil.dimensions_helper":  { en: "The four dimensions in the 16-axis model where this thinker scores highest. People in this archetype tend to lean the same way.", es: "Las cuatro dimensiones del modelo de 16 ejes en las que este pensador puntúa más alto. Las personas de este arquetipo suelen inclinarse en la misma dirección.", fr: "Les quatre dimensions du modèle à 16 axes où ce penseur obtient les scores les plus élevés. Les personnes de cet archétype tendent à pencher dans le même sens.", pt: "As quatro dimensões do modelo de 16 eixos em que este pensador pontua mais alto. Pessoas neste arquétipo tendem a inclinar-se da mesma forma.", ru: "Четыре измерения шестнадцатимерной модели, по которым этот мыслитель набирает наибольшие значения. Люди этого архетипа обычно склоняются туда же.", zh: "在 16 维模型中，这位思想家得分最高的四个维度。属于这一原型的人通常也朝同一方向倾斜。", ja: "16 軸モデルのうち、この思想家が最も高く位置する 4 つの次元。このアーキタイプの人々も、同じ方向に傾く傾向があります。", ko: "16축 모델에서 이 사상가가 가장 높게 위치하는 네 가지 차원. 이 원형에 속하는 사람들도 같은 방향으로 기울어지는 경향이 있습니다." },
  "phil.section_nearest":    { en: "Closest minds in the constellation", es: "Mentes más cercanas en la constelación", fr: "Esprits les plus proches dans la constellation", pt: "Mentes mais próximas na constelação", ru: "Ближайшие умы в созвездии", zh: "星座中最相近的心灵", ja: "コンステレーションで最も近い精神", ko: "별자리에서 가장 가까운 정신들" },
  "phil.nearest_helper":     { en: "The six thinkers whose 16-dimensional positions sit closest to this one. Useful as next-reading suggestions.", es: "Los seis pensadores cuyas posiciones de 16 dimensiones están más cerca de esta. Útil como sugerencias de lectura para continuar.", fr: "Les six penseurs dont les positions à 16 dimensions sont les plus proches de celle-ci. Utile comme suggestions de lectures complémentaires.", pt: "Os seis pensadores cujas posições de 16 dimensões estão mais próximas desta. Útil como sugestões de leitura complementar.", ru: "Шесть мыслителей, чьи положения в 16-мерном пространстве ближе всего к этому. Полезно как подсказки для дальнейшего чтения.", zh: "16 维空间中位置最接近此人的六位思想家。可作为延伸阅读的建议。", ja: "16 次元空間でこの人物に最も近い 6 名の思想家。次に読む候補として参考になります。", ko: "16차원 공간에서 이 사람에게 가장 가까운 여섯 명의 사상가. 다음 읽기 제안으로 유용합니다." },
  "phil.section_exercises":  { en: "Practices in their lineage", es: "Prácticas en su linaje", fr: "Pratiques dans leur lignée", pt: "Práticas em sua linhagem", ru: "Практики из их традиции", zh: "他们传承中的练习", ja: "この系譜の実践", ko: "이들 계보의 실천" },
  "phil.exercises_helper":   { en: "Short exercises in the same tradition as {name}'s thought. Each takes 5–25 minutes.", es: "Ejercicios breves en la misma tradición que el pensamiento de {name}. Cada uno toma de 5 a 25 minutos.", fr: "Brefs exercices dans la même tradition que la pensée de {name}. Chacun prend de 5 à 25 minutes.", pt: "Exercícios breves na mesma tradição do pensamento de {name}. Cada um leva de 5 a 25 minutos.", ru: "Короткие упражнения в той же традиции, что и мысль {name}. Каждое занимает 5–25 минут.", zh: "与 {name} 思想同一传统中的短练习。每个 5–25 分钟。", ja: "{name} の思想と同じ系譜にある短い実践。各 5〜25 分。", ko: "{name}의 사상과 같은 계보에 있는 짧은 실천들. 각 5~25분 소요." },
  "phil.topics_helper":      { en: "Concepts where {name} sits in the conversation. Each links to a primer.", es: "Conceptos donde {name} participa en la conversación. Cada uno enlaza a una introducción.", fr: "Les concepts où {name} prend part à la conversation. Chacun renvoie à une introduction.", pt: "Conceitos onde {name} participa da conversa. Cada um leva a uma introdução.", ru: "Понятия, в обсуждении которых участвует {name}. Каждое ведёт к краткому введению.", zh: "{name} 参与其中的那些概念。每一个都链接到一篇导读。", ja: "{name} が議論に加わる概念。それぞれが入門ページにリンクします。", ko: "{name}이(가) 대화에 참여하는 개념들. 각 항목은 입문 글로 연결됩니다." },
  "phil.matchups_helper":    { en: "Side-by-side with other philosophers, dimension by dimension.", es: "Lado a lado con otros filósofos, dimensión por dimensión.", fr: "Côte à côte avec d'autres philosophes, dimension par dimension.", pt: "Lado a lado com outros filósofos, dimensão por dimensão.", ru: "Бок о бок с другими философами, измерение за измерением.", zh: "与其他哲学家并置对照，逐个维度地比较。", ja: "他の哲学者と並べて、次元ごとに比較します。", ko: "다른 철학자들과 나란히, 차원별로 비교합니다." },
  "phil.cta_text":           { en: "Curious where you'd sit relative to {name}?", es: "¿Curioso/a por saber dónde te situarías respecto a {name}?", fr: "Curieux·se de savoir où tu te situerais par rapport à {name} ?", pt: "Curioso para saber onde você se situaria em relação a {name}?", ru: "Хотите узнать, где вы окажетесь относительно {name}?", zh: "想知道你与 {name} 相比会落在哪里？", ja: "{name} と比べて、自分がどこに位置するか気になりませんか？", ko: "{name}과 비교해 자신이 어디에 위치할지 궁금하신가요?" },
  "phil.cta_button":         { en: "Take the quiz", es: "Hacer el test", fr: "Passer le quiz", pt: "Fazer o quiz", ru: "Пройти тест", zh: "开始测验", ja: "クイズを受ける", ko: "퀴즈 시작하기" },

