  "topic.dimensions_helper": { en: "When you take the quiz, the dimensions most relevant to {title} are:", es: "Cuando haces el test, las dimensiones más relevantes para {title} son:", fr: "Quand tu fais le quiz, les dimensions les plus pertinentes pour {title} sont :", pt: "Quando você faz o quiz, as dimensões mais relevantes para {title} são:", ru: "Когда вы проходите тест, наиболее значимые для «{title}» измерения — это:", zh: "当你做测验时，与「{title}」最相关的维度是：", ja: "クイズを受けるとき、{title} に最も関わる次元は次のとおりです：", ko: "퀴즈를 풀 때 {title}과(와) 가장 관련된 차원은 다음과 같습니다:" },
