  "pub.trail_caption": { en: "Faded dots show the last {count} positions, threaded by a dashed line.", es: "Los puntos atenuados muestran las últimas {count} posiciones, enlazadas por una línea discontinua.", fr: "Les points pâles montrent les {count} dernières positions, reliés par une ligne pointillée.", pt: "Os pontos apagados mostram as últimas {count} posições, ligadas por uma linha tracejada.", ru: "Бледные точки — последние {count} позиций, соединённые пунктирной линией.", zh: "浅色圆点是最近 {count} 个位置，由虚线串联。", ja: "薄い点は直近 {count} 個の位置で、点線でつながれています。", ko: "흐릿한 점은 최근 {count}개의 위치이며, 점선으로 연결됩니다." },
  "pub.trail_caption_no_count": { en: "Faded dots show recent positions, threaded by a dashed line.", es: "Los puntos atenuados muestran posiciones recientes, enlazadas por una línea discontinua.", fr: "Les points pâles montrent les positions récentes, reliés par une ligne pointillée.", pt: "Os pontos apagados mostram posições recentes, ligadas por uma linha tracejada.", ru: "Бледные точки — недавние позиции, соединённые пунктирной линией.", zh: "浅色圆点是近期的位置，由虚线串联。", ja: "薄い点は最近の位置を示し、点線でつながれています。", ko: "흐릿한 점은 최근 위치들을 점선으로 이어 보여줍니다." },

