  "debate.pick_a": { en: "Pick a thinker for A.", es: "Elige un pensador para A.", fr: "Choisis un penseur pour A.", pt: "Escolha um pensador para A.", ru: "Выберите мыслителя для A.", zh: "请为 A 选择一位思想家。", ja: "A の思想家を選んでください。", ko: "A 측 사상가를 고르세요." },
