  "pilgrimage.meta_title":       { en: "The Pilgrimage · Mull", zh: "朝圣之旅 · Mull" },
  "pilgrimage.meta_desc":        { en: "A 30-day course personalized to your philosophical archetype. Daily prompts, slow drift, real momentum.", zh: "一门为你的哲学原型量身定制的 30 天课程。每日提示，缓慢漂移，真实的前行。" },
