  "pilgrimage.header_title":     { en: "A 30-DAY COURSE FOR YOU", zh: "一门为你而设的 30 天课程" },
  "pilgrimage.header_subtitle":  { en: "Most reflection apps give the same prompts to everyone. This one gives you an arc shaped for your archetype, with a lens tuned to your secondary flavor. Thirty days of daily prompts that move with you — and a visible chart of how your map shifts across them.", zh: "大多数反思类应用给每个人相同的提示。而这一门，为你的原型塑造一条专属弧线，并以贴合你次要倾向的视角加以调校。三十天的每日提示与你同行——还有一张清晰的图表，记录你的地图在这期间如何变化。" },
  "pilgrimage.back_mull":        { en: "← Back to Mull", zh: "← 返回 Mull" },
  "pilgrimage.loading_landing":  { en: "Loading your pilgrimage…", zh: "正在载入你的朝圣之旅……" },
