  "inst.ios_step3_title": { en: "Confirm the name \"Mull\" and tap \"Add\"", zh: "确认名称「Mull」，然后点击「添加」" },
  "inst.ios_step3_detail": { en: "iOS may suggest a longer name — feel free to shorten it. The tile is now on your home screen.", zh: "iOS 可能会建议一个更长的名字——你可以随意把它改短。图标现在已经在你的主屏幕上了。" },
  "inst.ios_notes": { en: "If you don't see \"Add to Home Screen\", you're either in private browsing or in a browser that isn't Safari. Both block the install.", zh: "如果你看不到「添加到主屏幕」，要么是在无痕浏览模式下，要么用的不是 Safari。这两种情况都会阻止安装。" },
