  "inst.android_step1_detail": { en: "It's labeled \"More\" or shown as ⋮. In Firefox the menu lives in the bottom-right.", zh: "它标着「更多」，或显示为 ⋮。在 Firefox 里，这个菜单在右下角。" },
  "inst.android_step2_title": { en: "Tap \"Install app\" or \"Add to Home screen\"", zh: "点击「安装应用」或「添加到主屏幕」" },
  "inst.android_step2_detail": { en: "Chrome and Edge show \"Install app\" once they detect Mull as a PWA. Firefox calls it \"Install\" or \"Add to Home screen\" depending on version.", zh: "Chrome 和 Edge 检测到 Mull 是 PWA 后，会显示「安装应用」。Firefox 则视版本不同，称之为「安装」或「添加到主屏幕」。" },
  "inst.android_step3_title": { en: "Confirm and the tile drops onto your home screen", zh: "确认后，图标就会出现在你的主屏幕上" },
  "inst.android_step3_detail": { en: "Some launchers (Samsung, Pixel) ask whether you want a shortcut or a full install — choose Install for the full-screen experience.", zh: "某些桌面启动器（三星、Pixel）会问你要快捷方式还是完整安装——想要全屏体验就选「安装」。" },
  "inst.android_notes": { en: "Long-press the Mull tile after install for shortcuts straight to Daily Spar, Pilgrimage, or The Inheritor.", zh: "安装后长按 Mull 图标，即可获得直达 Daily Spar、Pilgrimage 或 The Inheritor 的快捷方式。" },
  "inst.desktop_title": { en: "Desktop (Chrome, Edge, Brave)", zh: "桌面端（Chrome、Edge、Brave）" },
  "inst.desktop_preface": { en: "Chromium browsers on macOS, Windows, and Linux can install Mull as a standalone window. Safari on macOS doesn't support web app install — for that, just bookmark and pin the tab.", zh: "macOS、Windows 和 Linux 上的 Chromium 浏览器，都能把 Mull 安装为独立窗口。macOS 上的 Safari 不支持安装网页应用——那就把它加入书签并固定标签页吧。" },
  "inst.desktop_step1_title": { en: "Look for the install icon in the address bar", zh: "在地址栏里找到安装图标" },
  "inst.desktop_step1_detail": { en: "A small monitor-with-a-down-arrow icon appears at the right edge of the URL bar when a site is installable.", zh: "当网站可安装时，地址栏右端会出现一个带向下箭头的小显示器图标。" },
  "inst.desktop_step2_title": { en: "Click it, then click \"Install\"", zh: "点击它，然后点击「安装」" },
  "inst.desktop_step2_detail": { en: "Mull opens in its own window, separate from your other tabs. The Dock / Taskbar gets a Mull entry.", zh: "Mull 会在自己的窗口里打开，与你其他的标签页分开。程序坞 / 任务栏里也会出现一个 Mull 入口。" },
  "inst.desktop_step3_title": { en: "Pin it for quick access", zh: "把它固定下来，方便随时打开" },
  "inst.desktop_step3_detail": { en: "Right-click the Dock icon (macOS) or Taskbar icon (Windows) and choose to keep it there.", zh: "右键点击程序坞图标（macOS）或任务栏图标（Windows），选择保留在那里。" },
  // Wandering Question page (wndr.)
  "wndr.meta_title": { en: "The Wandering Question · Mull", zh: "漫游之问 · Mull" },
  "wndr.meta_description": { en: "A single question travels with you across a week. Monday: start. Wednesday: kindred. Friday: far. Sunday: synthesis.", zh: "一个问题，陪你走过一整周。周一：起步。周三：同道。周五：远方。周日：综合。" },
  "wndr.eyebrow": { en: "▶ THE WANDERING QUESTION · WEEK {week}", zh: "▶ 漫游之问 · 第 {week} 周" },
  "wndr.title": { en: "ONE QUESTION. ONE WEEK.", zh: "一个问题，一整周。" },
  "wndr.subtitle": { en: "Different from the dilemma: not a one-shot. A question you carry from Monday to Sunday. Mull surfaces it on four beats across the week and helps you synthesize at the end.", zh: "与「困境」不同：这不是一次性的。这是一个你从周一带到周日的问题。Mull 会在一周的四个节点上把它呈现给你，并在最后帮你做综合。" },
  "wndr.back_to_mull": { en: "Back to Mull", zh: "返回 Mull" },
  "wndr.loading": { en: "Loading…", zh: "加载中…" },
  "wndr.this_weeks_question": { en: "THIS WEEK’S QUESTION", zh: "本周之问" },
  "wndr.beats_answered": { en: "{done} of 4 beats answered", zh: "已回答 4 个节点中的 {done} 个" },
  "wndr.scaffolding_note": { en: "The kindred and far minds are chosen from your own quiz coordinates — real thinkers near and far from you, not generated answers. The four beats are a scaffold for your week-long thinking; Sunday's synthesis is yours to write.", zh: "同道与远方的那些心灵，是依据你自己的测验坐标选出的——是与你相近或相远的真实思想者，而非生成的回答。这四个节点，是为你一整周的思考搭建的脚手架；周日的综合，由你亲自写下。" },
  "wndr.edit": { en: "EDIT", zh: "编辑" },
  "wndr.cancel": { en: "CANCEL", zh: "取消" },
  "wndr.placeholder": { en: "What comes? Brief is fine.", zh: "想到了什么？简短也无妨。" },
  "wndr.save_beat": { en: "SAVE {beat}", zh: "保存 {beat}" },
  // Wandering — kindred/far philosopher rosters (vector-space picks)
  "wndr.kindred_intro": { en: "Two minds nearest your own coordinates. Sit with how either would meet the question — then react to one.", zh: "与你坐标最相近的两个心灵。想一想他们各自会如何面对这个问题——然后回应其中之一。" },
  "wndr.far_intro": { en: "One mind far from yours on this question. Read where they diverge — then answer back.", zh: "在这个问题上，与你相去最远的一个心灵。看看他们在哪里与你分道——然后回应。" },
