  "wndr.no_vector_nudge": { en: "Take the quiz to meet the minds nearest — and furthest from — you on this question.", zh: "完成测验，便能遇见在这个问题上与你最近、也最远的那些心灵。" },
  "wndr.no_vector_cta": { en: "Find your coordinates ▶", zh: "找到你的坐标 ▶" },
