  // Reading Hour (coming soon) (rd.)
  "rd.header_eyebrow": { en: "▶ THE READING HOUR · BUILDING", zh: "▶ 阅读一小时 · 建设中" },
  "rd.header_title": { en: "ONE HOUR. ONE TEXT. FIVE PROMPTS.", zh: "一小时。一篇文本。五道提示。" },
  "rd.card_eyebrow": { en: "THE READING HOUR · BUILDING", zh: "阅读一小时 · 建设中" },
  "rd.card_title": { en: "An hour with a primary text", zh: "与一篇原始文本共度一小时" },
  "rd.pitch": { en: "A 60-minute reading session with a primary text Mull picks for you — chosen from your nearest philosophers. Five prompts fire at intervals during the hour (Pomodoro-style, but for thinking). Brief synthesis at the end you can save to your anthology.", zh: "一场 60 分钟的阅读，文本由 Mull 为你挑选——取自与你最相近的哲学家。这一小时里会间隔弹出五道提示（番茄钟式的，但用于思考）。结束时做一段简短的综述，可存入你的文集。" },
  "rd.doing_1": { en: "Mull picks a passage of the right length from a thinker close to you.", zh: "Mull 从与你相近的思想家那里挑出一段长度合适的文字。" },
  "rd.doing_2": { en: "Five prompts space out across the hour: notice the question, define a term, find the move, steelman one objection, write the line you'd remember.", zh: "五道提示分散在这一小时里：留意问题、界定一个术语、找出关键的一步、为一个反对意见做最有力的辩护、写下你愿意记住的一句话。" },
  "rd.doing_3": { en: "End-of-hour: a short synthesis form, with three sentences of yours and a kindred quote.", zh: "临近结束：一份简短的综述表，写下你的三句话和一句相契的引文。" },
  "rd.doing_4": { en: "Drops into your /atlas as Range + Depth XP.", zh: "成果计入你的 /atlas，记为广度 + 深度经验值。" },
  "rd.when": { en: "Building now. Earliest ship: Q3 2026. Needs ~80 hand-picked text excerpts before it can launch with substance.", zh: "正在建设中。最早上线：2026 年第三季度。需要约 80 段精挑细选的文本节选，才能有分量地推出。" },
  "rd.meantime": { en: "The Pilgrimage gives you a 30-day reading-shaped arc tuned to your archetype.", zh: "「朝圣之旅」会给你一段为你的原型量身定制、为期 30 天、形如阅读的旅程。" },
  "rd.back": { en: "← Back to Mull", zh: "← 返回 Mull" },
