  "topic.featured_for_you_note": { en: "Of all the questions here, this one sits on the dimensions that most define you.", zh: "在这里的所有问题中，唯有这一个，正落在最能定义你的那些维度上。" },
  "topic.read": { en: "READ", zh: "阅读" },
  "topic.cta_body": { en: "Not sure where you sit on any of this yet? Take the 5-minute Inheritor quiz — it places you on the map and tells you which philosophers think most like you.", zh: "还不确定自己在这一切之中身处何方？花五分钟做一做“传承者”测验——它会把你标定在地图上，并告诉你哪些哲学家与你的思考方式最为相近。" },
  "topic.cta_button": { en: "Take the quiz", zh: "开始测验" },
  "topic.cat.big-questions.label": { en: "The big questions", zh: "大哉之问" },
  "topic.cat.big-questions.blurb": { en: "The puzzles philosophers keep returning to — about freedom, mind, identity, and what is.", zh: "哲学家反复回到的那些谜题——关于自由、心智、身份，以及“存在”本身。" },
  "topic.cat.schools.label": { en: "Schools of thought", zh: "思想流派" },
  "topic.cat.schools.blurb": { en: "The named movements — stoicism, existentialism, pragmatism. Different starting points, different answers.", zh: "那些有名有姓的思潮——斯多葛主义、存在主义、实用主义。不同的出发点，不同的答案。" },
  "topic.cat.eastern.label": { en: "Eastern traditions", zh: "东方传统" },
  "topic.cat.eastern.blurb": { en: "Three traditions that shaped half the world — and got mostly cut from the Western syllabus.", zh: "三大传统塑造了半个世界——却大多被西方的课程表删去。" },
  "topic.cat.ethics.label": { en: "Ethics & how to live", zh: "伦理与如何生活" },
  "topic.cat.ethics.blurb": { en: "What we owe each other. What makes a life good. How to act when the rules run out.", zh: "我们彼此亏欠什么。怎样的人生才算美好。当规则失效时，又该如何行事。" },
  "topic.cat.knowledge-beauty.label": { en: "Knowledge & beauty", zh: "知识与美" },
  "topic.cat.knowledge-beauty.blurb": { en: "How we know what we know. What makes something beautiful. The theory side of the map.", zh: "我们如何知道自己所知。是什么让事物成其为美。这是地图上偏理论的一侧。" },
